CREATE OR REPLACE FUNCTION lr_serverless_aws_us_catalog.bricksurance_policy.fn_earn_premium(in_policy_id STRING COMMENT 'The policy to earn premium for.')
RETURNS DECIMAL(18,2)
COMMENT 'Earned premium to date for a policy, derived live on a straight-line daily basis over the cover period - never a stored balance. This is the governed earning engine: the same math the premium_earning view uses, callable per policy so any workbench earns premium the one agreed way. Returns: Gross earned premium to date in policy currency; 0 if none written.'
RETURN (SELECT CAST(COALESCE(SUM(pt.amount * LEAST(1.0, GREATEST(0.0,
      (datediff(LEAST(current_date(), p.expiry_date), p.inception_date) + 1) / 365.0))), 0)
    AS DECIMAL(18,2))
 FROM lr_serverless_aws_us_catalog.bricksurance_policy.premium_transaction pt
 JOIN lr_serverless_aws_us_catalog.bricksurance_policy.policy p ON p.policy_id = pt.policy_id
 WHERE pt.policy_id = in_policy_id);
